export type Severity = "critical" | "medium" | "normal" | "nodata";
export type Status = "New" | "Acknowledged" | "In Repair" | "Closed";

// IEC 62446-3 Category of Anomaly (COA) labels — matches the inspection report's
// severity taxonomy. Internal rank keys (critical/medium/normal/nodata) are kept
// unchanged everywhere else so sorting, filtering, colors, and the API contract
// don't need to change — only the displayed label does.
export const SEVERITY_LABEL: Record<Severity, string> = {
  critical: "COA3",
  medium:   "COA2",
  normal:   "COA1",
  nodata:   "—",
};

/**
 * Client-facing spelling of the same taxonomy.
 *
 * A plant owner reading "COA3" has to be taught what it means; "Critical" needs
 * no gloss and carries the action implicitly. The code is kept in brackets so a
 * dot on the map still ties back to the COA column in the PDF report — dropping
 * it entirely would sever that link. Use this wherever a reading customer sees
 * the label in prose or in a control: map legend and filters, the anomaly-list
 * severity filter, the WhatsApp share text, and size="lg" severity badges.
 *
 * Keep SEVERITY_LABEL for two cases. First, size="sm" badges, which sit in a
 * 9-column table cell and the dashboard grid where the full label is ~2x too
 * wide. Second — and this one is a contract, not a preference — the exports:
 * the Severity column of the CSV in routes/_app/anomalies/index.tsx, and both
 * the balloon body and the folder names in lib/kml.ts, where the bare code is
 * the established value that downstream consumers parse. (Note the CSV importer
 * in lib/csv.ts is unrelated: it has its own alias vocabulary and never reads
 * either of these maps.)
 */
export const SEVERITY_LABEL_FULL: Record<Severity, string> = {
  critical: "Critical (COA3)",
  medium:   "Medium (COA2)",
  normal:   "Normal (COA1)",
  nodata:   "No Data",
};

export type RootCause =
  | "Manufacturing defect"
  | "Wiring / connector fault"
  | "Soiling / dust"
  | "Shading / vegetation"
  | "Physical damage"
  | "Unknown"
  | null;

export interface Anomaly {
  id: string;
  panelId: string;
  row: number;
  col: number;
  type: string;
  deltaT: number | null;
  deltaTNorm: number | null;  // IEC 62446-3 normalised to 1000 W/m²
  severity: Severity;
  string: string;
  inverter: string;
  status: Status;
  rootCause: RootCause;
  date: string;
  inspectionTime: string;
  rgbNote: string;
  gps: { lat: number; lng: number };
  /** Actual panel outline surveyed from drone imagery (defpanels1.kml), [lng, lat] pairs, closed ring */
  footprint?: [number, number][];
  /**
   * Asset-register position, straight off the survey KML.
   *
   * The Block 20 set had nowhere to put these — its deliverable only carried
   * table and inverter — so they are optional and every consumer must cope with
   * them being absent. They are what a field engineer actually navigates by:
   * "block 16, SMB 09, table 212, rack 275, module A - 8" locates a panel on the
   * ground far faster than a lat/lng does.
   */
  block?: string;
  smb?: string;
  /** Which of the rack's two strings — "A" or "B". */
  stringSide?: string;
  /** Module position on the rack, as printed on the layout, e.g. "A - 8". */
  module?: string;
  /** Raw two-letter code from the inspection KML (MM, MC, SP, BD, MB, SC, SO, SH). */
  defectCode?: string;
  peakTemp?: number;
  refTemp?: number;
  irradiance?: number;
  moduleSerial?: string;
  dailyLossINR?: number;
  dailyLossKWh?: number;
}

// ─── Primary plant (March 2026 inspection data) ──────────────────────────────

/**
 * Plant header figures for the March 2026 survey.
 *
 * `totalPanels` is derived, not supplied — the deliverable is a defect list, so
 * it says nothing directly about healthy modules. The asset register inside it
 * does: racks are numbered 1..415 with only nine numbers unused (406 of 415
 * appear), rack numbering never crosses a block boundary, and no rack ever shows
 * a module position above 26. A dense 1..415 range is what you see when the
 * sample has nearly saturated the population, so 415 racks x 26 modules = 10,790
 * is the register's own size rather than an extrapolation from it.
 *
 * `capacityMW` follows from that at the Block 20 module rating (10 MW / 19,058
 * modules = 525 W), which is the only rating we have been given for this site.
 * Both numbers are worth confirming against the client's asset list before they
 * appear in a signed report; the defect figures beside them are measured and
 * need no such caveat.
 */
export const plant = {
  name: "Blocks 06-122 Solar Plant",
  location: "Rajasthan, India",
  capacityMW: 5.7,
  totalPanels: 10790,
  lastInspection: "31 March 2026",
  nextInspection: "30 June 2026",
  // 9,600 of 10,790 modules unflagged. Matches severityCounts.normal below —
  // they are shown side by side on the dashboard and must not disagree.
  healthScore: 89,
  // Sum of the per-anomaly dailyLossINR that _enrich() derives, over the 1,190
  // COA2/COA3 findings (COA1 soiling and shading are not priced). Recompute this
  // whenever _TYPE_LOSS_INR changes or a new survey lands.
  dailyLossINR: 202770,
  dailyLossKWh: 45059,
  feedInTariff: 4.5,
};

// ─── Anomalies — March 2026 survey (1,249 panels, sorted: critical → medium → normal) ───
//
// Generated by scripts/import_defect_kml.py from defpanels1.kml — do not hand-edit.
// Re-run it against the next deliverable rather than patching entries here; at
// 1,249 rows a manual merge cannot be reviewed, and the two-letter defect-code
// mapping that decides `type` and `severity` lives in that script where it can be
// read as a table.
//
// `footprint` rings and `gps` centroids come from the KML unmodified. Every one of
// the 1,249 lands on a data pixel of the thermal overlay (see the note in
// lib/overlay-registration.ts), so a marker that looks misplaced on the map is a
// real finding about the survey, not a registration artefact.

// Raw entries omit deltaTNorm/rootCause — _enrich() fills them in
type RawAnomaly = Omit<Anomaly, "deltaTNorm" | "rootCause">;

/**
 * The cast at the foot of this array is load-bearing, not laziness.
 *
 * Annotating the literal directly — `const _rawAnomalies: RawAnomaly[] = [...]`,
 * which is what the 347-row Block 20 version did and what you will reach for
 * first — fails on this dataset with:
 *
 *     TS2590: Expression produces a union type that is too complex to represent.
 *
 * Checking 1,249 object literals against `severity: Severity` and against
 * `footprint: [number, number][]` (a tuple, so every one of the ~6,200 coordinate
 * pairs is a separate assignability check) exceeds what the compiler will model.
 * The limit is the checker's, not the data's.
 *
 * So the shape is guaranteed upstream instead: scripts/import_defect_kml.py emits
 * every field from a fixed template and maps `type`/`severity` through one table,
 * so a malformed row is not something this file can produce. If you ever edit an
 * entry here by hand you lose that guarantee and the compiler will not catch you —
 * which is the real reason to re-run the generator rather than patch rows.
 */
